% Entities
enum ENTITY = {Pedestrian, North_car, East_car, South_car, West_car};

% Decision variables: order in which each entity goes through (1 = first, 5 = last)
array[ENTITY] of var 1..5: order;

% All entities go in different positions
constraint alldifferent(order);

% Arrival times (lower = earlier)
array[ENTITY] of var 1..3: arrival;

% Clue 6: South car arrives before pedestrian and East car
constraint arrival[South_car] < arrival[Pedestrian];
constraint arrival[South_car] < arrival[East_car];

% Clue 5: Pedestrian and East car arrive at the same moment
constraint arrival[Pedestrian] = arrival[East_car];

% Clue 7: North car and West car arrive at the same moment, after pedestrian and East car
constraint arrival[North_car] = arrival[West_car];
constraint arrival[North_car] > arrival[Pedestrian];
constraint arrival[North_car] > arrival[East_car];

% Rule 1: Pedestrian at eastern crosswalk goes before East car
constraint order[Pedestrian] < order[East_car];

% Rule 2: Cars/pedestrian go in order of arrival
% If entity i arrives before entity j, then i goes before j
constraint forall(i, j in ENTITY where i != j)(
  arrival[i] < arrival[j] -> order[i] < order[j]
);

% Rule 3: If two entities arrive at the same moment, apply clockwise priority
% North, East, South, West priority order for ties

% Pedestrian and East car arrive together - pedestrian goes first (Rule 1 already covers this)

% North car and West car arrive together - North goes before West (clockwise priority)
constraint order[North_car] < order[West_car];

