constraint arrival[NorthCar] > arrival[Pedestrian];
constraint arrival[NorthCar] > arrival[EastCar];

% Rule 2: Otherwise, entities go in the order they arrive
% For entities with different arrival times, earlier arrival means earlier order
constraint forall(e1, e2 in ENTITY where e1 != e2)(
  arrival[e1] < arrival[e2] -> order[e1] < order[e2]
);

