enum PERSON = {Priya, Sam};
enum OUTCOME = {Denied, Approved, CounterOffer};

% Credit scores
array[PERSON] of int: credit_score = [680, 750];

% Financial data
int: combined_income = 9000;
int: combined_debt = 3200;
bool: amount_exceeds_limit = true;

% Decision variable
var OUTCOME: outcome;

% Rule 1: Credit tier uses lower score; if below 600, loan is Denied
int: lower_credit_score = min(credit_score);
constraint (lower_credit_score < 600) -> (outcome = Denied);

% Rule 2: DTI ratio; if exceeds 43%, loan is Denied
float: dti_ratio = int2float(combined_debt) / int2float(combined_income);
constraint (dti_ratio > 0.43) -> (outcome = Denied);

% Rule 3: If not denied and amount within limits, loan is Approved
constraint (lower_credit_score >= 600 /\ dti_ratio <= 0.43 /\ not amount_exceeds_limit) -> (outcome = Approved);

% Rule 4: If not denied but amount exceeds limits, Counter-Offer
constraint (lower_credit_score >= 600 /\ dti_ratio <= 0.43 /\ amount_exceeds_limit) -> (outcome = CounterOffer);

