include "globals.mzn";

enum PERSON = {Alice, Bob, Carol, Dave};
enum COLOR = {Red, Blue, Green, Yellow};
enum DRINK = {Tea, Coffee, Juice, Water};
enum PET = {Cat, Dog, Bird, Fish};

array[1..4] of var COLOR: color;
array[1..4] of var DRINK: drink;
array[1..4] of var PET: pet;

% Each person has one of each attribute
constraint alldifferent(color);
constraint alldifferent(drink);
constraint alldifferent(pet);

% Alice is at position 1
constraint exists(i in 1..4)(
  i = 1 /\ color[i] = Red /\ drink[i] = Tea
);

% Bob is at position 2
constraint exists(i in 1..4)(
  i = 2 /\ color[i] = Blue /\ drink[i] = Coffee
);

% Carol is at position 3
constraint exists(i in 1..4)(
  i = 3 /\ color[i] = Green /\ drink[i] = Juice
);

% Dave is at position 4
constraint exists(i in 1..4)(
  i = 4 /\ color[i] = Yellow /\ drink[i] = Water
);

% The person with Red has a Cat
constraint exists(i in 1..4)(
  color[i] = Red -> pet[i] = Cat
);

% The person with Blue has a Dog
constraint exists(i in 1..4)(
  color[i] = Blue -> pet[i] = Dog
);

% The person with Green has a Bird
constraint exists(i in 1..4)(
  color[i] = Green -> pet[i] = Bird
);

% The person with Yellow has a Fish
constraint exists(i in 1..4)(
  color[i] = Yellow -> pet[i] = Fish
);

include "globals.mzn";

% Houses
set of int: HOUSES = 1..3;

% Neighbors
enum NEIGHBOR = {Ana, Bo, Cy};

% Decision variable: which neighbor lives in which house
array[HOUSES] of var NEIGHBOR: house;

% Constraint: all neighbors live in different houses
constraint alldifferent(house);

% Constraint: Ana lives in house 1
constraint house[1] = Ana;

% Constraint: Bo does not live in house 2
constraint house[2] != Bo;

% Since the puzzle asks "which neighbor has the loudest laugh?" 
% but provides no information about laughs, we need to determine
% who lives where based on the constraints given.
% The question itself doesn't provide a solvable constraint about laughs.

% Decision variable for who has the loudest laugh
var NEIGHBOR: loudest_laugh;

% No constraints on loudest_laugh are given in the puzzle,
% so any neighbor could have the loudest laugh

