array[1..3] of var NEIGHBOR: house;

% Ana lives in house 1
constraint house[1] = Ana;

% Bo does not live in house 2
constraint house[2] != Bo;

% All neighbors live in different houses
constraint alldifferent(house);

include "globals.mzn";

% Houses are numbered 1 to 3
int: N = 3;
set of int: HOUSES = 1..N;

% Neighbors
enum NEIGHBOR = {Ana, Bo, Cy};

% Each neighbor lives in exactly one house
array[NEIGHBOR] of var HOUSES: house;

% Each house has exactly one neighbor
constraint alldifferent(house);

% Ana lives in house 1
constraint house[Ana] = 1;

% Bo does not live in house 2
constraint house[Bo] != 2;

% The puzzle asks which neighbor has the loudest laugh
% This is underdetermined by the given constraints
% We model it as a decision variable
var NEIGHBOR: loudest_laugh;

