enum ITEM = {Rice, Book, Skillet, FirstAid, Toolbox};

array[ITEM] of int: weight = [4, 3, 5, 2, 6];
array[ITEM] of int: value = [5, 4, 8, 6, 7];

array[ITEM] of var 0..1: packed;

constraint packed[FirstAid] = 1;

constraint sum(i in ITEM)(packed[i] * weight[i]) <= 10;

var int: total_value = sum(i in ITEM)(packed[i] * value[i]);

solve maximize total_value;

