enum ITEM = {IceCream, Beans, Flour, Bananas};
enum COMPARTMENT = {C1, C2, C3, C4};

array[ITEM] of var COMPARTMENT: item_location;

% Each item in exactly one compartment, each compartment has exactly one item
constraint alldifferent(item_location);

% Compartment 1 is a freezer (below freezing)
% Compartments 2, 3, 4 are unrefrigerated (above freezing)
% Ice cream melts above freezing, so it must be in the freezer
constraint item_location[IceCream] = C1;

